// Control UI tool icon set, split from icons.ts to keep both under the max-lines cap.
import { html, svg, type SVGTemplateResult, type TemplateResult } from "lit";

// Shared 24px icon shell for the Solar outline set. Solar draws an outline as a
// filled silhouette rather than a stroked path, so the whole registry renders
// through one fill contract; a stroked shell beside it would put two different
// weights in the same row. Bodies must be svg`` fragments: html`` would parse
// the shapes outside the SVG namespace and they would silently render nothing.
// Every body also repeats fill/stroke on its own root group: surface CSS sets
// `fill: none; stroke: currentColor` on the svg itself, which beats a
// presentation attribute here but never reaches a group inside the shell.
export function solarIcon(body: SVGTemplateResult): TemplateResult {
  return html`
    <svg data-lucide-icon="" viewBox="0 0 24 24" fill="currentColor" stroke="none">${body}</svg>
  `;
}

// Stroked shell for the handful of glyphs Solar outline has no honest match for
// (git topology, diff marks, panel splits, brand art). stroke-width 1.5 is the
// weight Solar outline silhouettes are drawn at, so a kept glyph sits at the
// same optical weight as its Solar neighbours; surfaces may still override it.
export function strokeIcon(body: SVGTemplateResult): TemplateResult {
  return html`
    <svg
      data-lucide-icon=""
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      stroke-width="1.5"
      stroke-linecap="round"
      stroke-linejoin="round"
    >
      ${body}
    </svg>
  `;
}

// Shell for glyphs drawn as one solid shape on a 16px grid instead of a 24px
// outline. Their filled silhouette carries the meaning, so they keep their own
// fill; pushing them through strokeIcon would hollow them out. The inner group
// carries the paint for the same reason solarIcon() repeats it.
export function fillIcon(body: SVGTemplateResult): TemplateResult {
  return html`
    <svg viewBox="0 0 16 16" fill="currentColor" stroke="none">
      <g fill="currentColor" stroke="none">${body}</g>
    </svg>
  `;
}

